<?php require_once __DIR__.'/../config/config.php'; require_admin(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['pending','paid','processing','shipped','completed','cancelled'];if(in_array($status,$allowed,true)){ $pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);audit('Alterou status do pedido para '.$status,$id);flash('ok','Pedido atualizado.');}redirect('orders.php?id='.$id);} $id=(int)($_GET['id']??0); $selected=$id?$pdo->prepare('SELECT * FROM orders WHERE id=?'):null;if($selected){$selected->execute([$id]);$order=$selected->fetch();$st=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$st->execute([$id]);$items=$st->fetchAll();}$rows=$pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();require __DIR__.'/includes/header.php'; ?><div class="content"><h1>Pedidos & Pagamentos</h1><div class="panel" style="margin:20px 0"><table class="table"><tr><th>#</th><th>Cliente</th><th>Total</th><th>Pagamento</th><th>Status</th><th></th></tr><?php foreach($rows as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><?=e($o['status'])?></td><td><a class="btn" href="orders.php?id=<?=$o['id']?>">Ver</a></td></tr><?php endforeach;?></table></div><?php if(!empty($order)):?><div class="panel"><h2>Pedido #<?=$order['id']?></h2><p><?=e($order['customer_name'])?> · <?=e($order['customer_email'])?> · <?=e($order['customer_phone'])?></p><p>Total: <strong><?=money($order['total'])?></strong> · Referência: <?=e($order['payment_reference']??'—')?></p><form method="post" class="actions" style="margin:15px 0"><?=csrf_field()?><input type="hidden" name="id" value="<?=$order['id']?>"><select name="status"><option value="pending">Pendente</option><option value="paid">Pago / aprovado</option><option value="processing">Em processamento</option><option value="shipped">Enviado</option><option value="completed">Concluído</option><option value="cancelled">Cancelado</option></select><button class="btn gold">Atualizar status</button></form><table class="table"><tr><th>Produto</th><th>Tamanho</th><th>Cor</th><th>Qtd.</th><th>Unit.</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=e($i['size'])?></td><td><?=e($i['color'])?></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
